import{_ as r,c as t,o as a,ae as o}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Progress Bar (Pro)","description":"Progress Bar (Pro)","frontmatter":{"title":"Progress Bar (Pro)","description":"Progress Bar (Pro)"},"headers":[],"relativePath":"guide/drag-drop-elements/progress-bar.md","filePath":"guide/drag-drop-elements/progress-bar.md"}'),s={name:"guide/drag-drop-elements/progress-bar.md"};function n(i,e,l,d,g,h){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="progress-bar-pro" tabindex="-1">Progress Bar (Pro) <a class="header-anchor" href="#progress-bar-pro" aria-label="Permalink to &quot;Progress Bar (Pro)&quot;">​</a></h1><p>Progress Bar, also known as “Circle Rating,” is only available in the Ninja Tables Drag and Drop module as a pro element. It shows progress status, availability, reviews, and statistical values in linear and circular formats, which are far more attractive than regular styles. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Progress-bar-element-1024x628.png" alt="Progress bar element"> You can add such a beautiful element by dragging it to your desired cell in Ninja Tables drag and drop. Let’s add the Progress Bar element to our table.</p><h2 id="properties-of-progress-bar-element" tabindex="-1"><strong>Properties of Progress Bar Element</strong> <a class="header-anchor" href="#properties-of-progress-bar-element" aria-label="Permalink to &quot;**Properties of Progress Bar Element**&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Option Name</strong></th><th><strong>Type</strong></th></tr></thead><tbody><tr><td>Progress Type</td><td>Linear, Circular, and Dashboard</td></tr><tr><td>Color</td><td>Graphical Color Select</td></tr><tr><td>Text Font Size</td><td>Numeric Value, drag bar</td></tr><tr><td>Progress Bar Percentage</td><td>Numeric Value, drag bar</td></tr><tr><td>Progress Bar Width</td><td>Numeric Value, drag bar</td></tr><tr><td>Progress Bar Thickness</td><td>Numeric Value, drag bar</td></tr><tr><td>Alignment</td><td>Left, Center, and Right</td></tr></tbody></table><ul><li>**Progress Type: **You can change the type of the Progress Element style. Available options are Linear, Circular, and Dashboard. The most used version is circular. By default, it is set to Circle.</li><li>**Color: **You can change the Color of the Progress Element. By default, it is set to Black.</li><li>**Text Font Size: **You can change the Text Size of the Progress Element. By default, it is set to 15</li><li>**Progress Bar Percentage: **You can even change the percentage of the Progress Bar. By default, it is set to 50%.</li><li>**Progress Bar Width: **You can change the width(size) of the Progress Bar. By default, it is set to 100.</li><li>**Progress Bar Thickness: **You can even change the thickness of the Progress Bar to make it thicker or thinner.</li><li>**Alignment: **You can align the Progress Bar to the left, right, or center. By default, it is set to Center.</li></ul><h2 id="conclusion" tabindex="-1"><strong>Conclusion</strong> <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;**Conclusion**&quot;">​</a></h2><p>In the example image shown above, we&#39;ve used all 3 types of Progress Bar elements. In that product table, circle, line, and dashboard progress bars show the available stocks of the products. But this element can also show progress of a certain project, how far people have read a book, or how good/bad the reviews are. Let us know your thoughts and questions in the comment box.</p>',7)])])}const p=r(s,[["render",n]]);export{u as __pageData,p as default};
